class ReportAccumulator:
    def __init__(self):
        self.total_revenue = 0
        self.total_orders = 0
        self.total_items = 0
        self.max_order = 0
        self.min_order = float('inf')
        self.status_counts = {}
        self.product_revenue = {}

    def update(self, order):
        val = order['value']
        self.total_revenue += val
        self.total_orders += 1
        self.total_items += len(order['items'])
        if val > self.max_order:
            self.max_order = val
        if val < self.min_order:
            self.min_order = val
        status = order['status']
        self.status_counts[status] = self.status_counts.get(status, 0) + 1
        for item in order['items']:
            pid = item['product_id']
            self.product_revenue[pid] = self.product_revenue.get(pid, 0) + item['price'] * item['qty']

    @property
    def summary(self):
        avg_order_value = self.total_revenue / self.total_orders if self.total_orders else 0
        min_order = self.min_order if self.min_order != float('inf') else 0
        top_products = sorted(self.product_revenue.items(), key=lambda x: x[1], reverse=True)[:5]
        return {
            'total_revenue': self.total_revenue,
            'total_orders': self.total_orders,
            'total_items': self.total_items,
            'avg_order_value': avg_order_value,
            'max_order': self.max_order,
            'min_order': min_order,
            'status_counts': self.status_counts,
            'top_products': top_products
        }

def generate_report(orders):
    accumulator = ReportAccumulator()
    for order in orders:
        accumulator.update(order)
    return accumulator.summary
